package com.salespunch360.mobile.ui.account.project
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.viewmodel.compose.viewModel
import com.salespunch360.mobile.ProjectMaterialViewModel
import com.salespunch360.mobile.account.str
import com.salespunch360.mobile.ui.account.sales.SelectField
@Composable fun ProjectMaterialScreen(padding:PaddingValues,vm:ProjectMaterialViewModel=viewModel()){val s=vm.state.collectAsStateWithLifecycle().value;val options=listOf("ISSUE" to "Issue inventory","CONSUME" to "Consume","RETURN" to "Return to inventory","TRANSFER" to "Transfer Project");LazyColumn(Modifier.fillMaxSize().padding(padding),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text("Project Material",style=MaterialTheme.typography.headlineSmall)};if(s.loading)item{LinearProgressIndicator(Modifier.fillMaxWidth())};s.error?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}};s.message?.let{item{Text(it,color=MaterialTheme.colorScheme.primary)}};item{SelectField("Action",s.action,options){v->vm.update{it.copy(action=v)}}};item{SelectField(if(s.action=="TRANSFER")"Source Project" else "Project",s.projectId,s.projects.map{it.str("id") to "${it.str("projectNumber")} · ${it.str("name")}"}){v->vm.update{it.copy(projectId=v)}}};if(s.action=="TRANSFER")item{SelectField("Destination Project",s.destinationProjectId,s.projects.filter{it.str("id")!=s.projectId}.map{it.str("id") to it.str("name")}){v->vm.update{it.copy(destinationProjectId=v)}}};if(s.action=="ISSUE"){item{SelectField("Warehouse",s.warehouseId,s.warehouses.map{it.str("id") to it.str("name")}){v->vm.update{it.copy(warehouseId=v)}}};item{SelectField("Product",s.productId,s.products.map{it.str("id") to it.str("name")}){v->vm.update{it.copy(productId=v)}}};item{SelectField("Budget line",s.budgetLineId,s.budgetLines.filter{it.str("projectId")==s.projectId}.map{it.str("id") to it.str("title")}){v->vm.update{it.copy(budgetLineId=v)}}}}else item{SelectField("Original material",s.sourceMovementId,s.movements.filter{it.str("projectId")==s.projectId&&it.str("movementType") in listOf("DIRECT_PROJECT_RECEIPT","INVENTORY_ISSUE_TO_PROJECT","TRANSFER_IN")}.map{it.str("id") to "${it.str("productId")} · ${it.str("quantity")}"}){v->vm.update{it.copy(sourceMovementId=v)}}};if(s.action=="RETURN")item{SelectField("Destination warehouse",s.warehouseId,s.warehouses.map{it.str("id") to it.str("name")}){v->vm.update{it.copy(warehouseId=v)}}};item{OutlinedTextField(s.quantity,{v->vm.update{it.copy(quantity=v)}},label={Text("Quantity")},modifier=Modifier.fillMaxWidth())};if(s.action in listOf("RETURN","TRANSFER"))item{OutlinedTextField(s.reason,{v->vm.update{it.copy(reason=v)}},label={Text("Reason")},modifier=Modifier.fillMaxWidth())};item{OutlinedTextField(s.notes,{v->vm.update{it.copy(notes=v)}},label={Text("Notes")},modifier=Modifier.fillMaxWidth())};item{Button(vm::post,enabled=!s.saving,modifier=Modifier.fillMaxWidth()){Text(if(s.saving)"Posting…" else "Post ${s.action.lowercase()}")}};item{Text("Movement history",style=MaterialTheme.typography.titleLarge)};items(s.movements,key={it.str("id")}){m->ListItem(headlineContent={Text(m.str("movementType").replace('_',' '))},supportingContent={Text("Qty ${m.str("quantity")}")},trailingContent={Text("₹${m.str("totalCost")}")})}}}
